/** Sign order.bulk_orders: every element of orders on its own, with its own nonce and expiration. Each order is signed on its own, like create_order: OrderWithBuilderFee when that order's builder is set to a non-zero address, otherwise Order. The cancel lists and time_to_live_ms are not signed. */
export async function signOrderBulkOrders(
  rt: Runtime,
  req: m.ApiBulkOrdersRequestInput,
): Promise<m.ApiBulkOrdersRequestInput> {
  const pending: [w.WireSignature, StructType, Message][] = [];
  for (const element of w.each(req.orders)) {
    const d: m.ApiCreateOrderRequestInput = { order: element };
    const sig = ((d.order ??= {}).signature ??= {});
    w.prepareSignature(rt, sig, SIGNATURE_TTL_NS);
    const meta = await metadata(rt, w.present(w.each(d.order?.legs).map((e) => e.instrument)), []);
    if (rt.checkOrders) checkOrder(ORDER_CHECKS, d.order, meta);
    let st: StructType;
    let message: Message;
    if (w.addressSet(d.order?.builder)) {
      st = EIP712_ORDER_WITH_BUILDER_FEE;
      message = messageOrderWithBuilderFee(d, meta);
    } else {
      st = EIP712_ORDER;
      message = messageOrder(d, meta);
    }
    pending.push([sig, st, message]);
  }
  for (const [sig, st, message] of pending) await w.signInto(rt, sig, st, message);
  return req;
}

/** Sign order.create_order. Use OrderWithBuilderFee when order.builder is set to a non-zero address, otherwise Order. */
export async function signOrderCreateOrder(
  rt: Runtime,
  d: m.ApiCreateOrderRequestInput,
): Promise<m.ApiCreateOrderRequestInput> {
  const sig = ((d.order ??= {}).signature ??= {});
  w.prepareSignature(rt, sig, SIGNATURE_TTL_NS);
  const meta = await metadata(rt, w.present(w.each(d.order?.legs).map((e) => e.instrument)), []);
  if (rt.checkOrders) checkOrder(ORDER_CHECKS, d.order, meta);
  let st: StructType;
  let message: Message;
  if (w.addressSet(d.order?.builder)) {
    st = EIP712_ORDER_WITH_BUILDER_FEE;
    message = messageOrderWithBuilderFee(d, meta);
  } else {
    st = EIP712_ORDER;
    message = messageOrder(d, meta);
  }
  await w.signInto(rt, sig, st, message);
  return d;
}

