/** Sign transfer.transfer. If from_wallet_type and to_wallet_type are both set: TransferV2 when the currency id fits uint8 (<= 255), else TransferV3. If neither is set: Transfer (only for currency ids <= 255). Setting only one... */
export async function signTransferTransfer(
  rt: Runtime,
  d: m.ApiTransferRequestInput,
): Promise<m.ApiTransferRequestInput> {
  const sig = (d.signature ??= {});
  w.prepareSignature(rt, sig, SIGNATURE_TTL_NS);
  const meta = await metadata(rt, [], w.present([d.currency]));
  let st: StructType;
  let message: Message;
  const currencyId = meta.currency(d.currency).id;
  const [fromWallet, toWallet] = [d.from_wallet_type, d.to_wallet_type];
  if (!fromWallet !== !toWallet)
    throw new SigningError("set both from_wallet_type and to_wallet_type, or neither");
  if (!fromWallet) {
    if (currencyId > 255)
      throw new SigningError(`currency id ${currencyId} needs from_wallet_type and to_wallet_type`);
    st = EIP712_TRANSFER;
    message = messageTransfer(d, meta);
  } else if (currencyId <= 255) {
    st = EIP712_TRANSFER_V2;
    message = messageTransferV2(d, meta);
  } else {
    st = EIP712_TRANSFER_V3;
    message = messageTransferV3(d, meta);
  }
  await w.signInto(rt, sig, st, message);
  return d;
}

/** Sign transfer.withdrawal. Withdrawal when the currency id fits uint8 (<= 255), else WithdrawalV2. */
export async function signTransferWithdrawal(
  rt: Runtime,
  d: m.ApiWithdrawalRequestInput,
): Promise<m.ApiWithdrawalRequestInput> {
  const sig = (d.signature ??= {});
  w.prepareSignature(rt, sig, SIGNATURE_TTL_NS);
  const meta = await metadata(rt, [], w.present([d.currency]));
  let st: StructType;
  let message: Message;
  if (meta.currency(d.currency).id <= 255) {
    st = EIP712_WITHDRAWAL;
    message = messageWithdrawal(d, meta);
  } else {
    st = EIP712_WITHDRAWAL_V2;
    message = messageWithdrawalV2(d, meta);
  }
  await w.signInto(rt, sig, st, message);
  return d;
}

